"""Parser for standard five-field cron expressions.

    minute  hour  day_of_month  month  day_of_week

Each field supports wildcards (``*``), single values (``42``), ranges (``1-5``),
lists (``1,3,5``) and steps (``*/15``, ``1-30/5``).

    >>> parse_cron("0 12 * * 1-5").describe()
    'At 12:00 on Monday through Friday'
    >>> parse_cron("*/15 * * * *").describe()
    'Every 15 minutes'

The module is organised top-down: the data model first (it is the vocabulary
everything else uses), then parsing, then description rendering, then the small
text helpers at the bottom.
"""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime
from typing import Sequence

__all__ = ["CronParseError", "CronField", "CronSchedule", "parse_cron"]


class CronParseError(ValueError):
    """Raised when an expression is not a valid cron expression."""


# ---------------------------------------------------------------------------
# Data model
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class FieldSpec:
    """The static definition of one cron field: its name and legal range."""

    name: str
    min_value: int
    max_value: int

    @property
    def full_range(self) -> range:
        """Every value the field accepts, in ascending order."""
        return range(self.min_value, self.max_value + 1)


MINUTE = FieldSpec("minute", 0, 59)
HOUR = FieldSpec("hour", 0, 23)
DAY_OF_MONTH = FieldSpec("day_of_month", 1, 31)
MONTH = FieldSpec("month", 1, 12)
DAY_OF_WEEK = FieldSpec("day_of_week", 0, 6)  # 0 = Sunday

#: Field specs in the order they appear in an expression.
FIELD_SPECS: tuple[FieldSpec, ...] = (MINUTE, HOUR, DAY_OF_MONTH, MONTH, DAY_OF_WEEK)


@dataclass(frozen=True)
class CronField:
    """One parsed field: its spec, the text it came from, and the values it matches."""

    spec: FieldSpec
    source: str
    values: tuple[int, ...]  # sorted and de-duplicated

    def matches(self, value: int) -> bool:
        return value in self.values

    @property
    def is_unrestricted(self) -> bool:
        """True when the field matches every value in its range (``*``, ``0-59``, ...)."""
        return len(self.values) == len(self.spec.full_range)

    @property
    def is_single_value(self) -> bool:
        return len(self.values) == 1

    @property
    def only_value(self) -> int:
        """The single matching value. Only valid when :attr:`is_single_value`."""
        if not self.is_single_value:
            raise ValueError(f"{self.spec.name} matches {len(self.values)} values, not one")
        return self.values[0]

    @property
    def wildcard_step(self) -> int | None:
        """Step size ``n`` when the field was written ``*/n`` with ``n`` > 1, else None."""
        if not self.source.startswith("*/"):
            return None
        step = int(self.source[2:])  # already validated during parsing
        return step if step > 1 else None

    @property
    def is_contiguous_run(self) -> bool:
        """True when the values form an unbroken run of three or more (e.g. ``1-5``)."""
        if len(self.values) < 3:
            return False
        return self.values[-1] - self.values[0] == len(self.values) - 1


@dataclass(frozen=True)
class CronSchedule:
    """A fully parsed cron expression."""

    expression: str
    minute: CronField
    hour: CronField
    day_of_month: CronField
    month: CronField
    day_of_week: CronField

    @property
    def fields(self) -> tuple[CronField, ...]:
        """The five fields in expression order."""
        return (self.minute, self.hour, self.day_of_month, self.month, self.day_of_week)

    def describe(self) -> str:
        """Render the schedule as an English sentence fragment."""
        time_phrase = describe_time_of_day(self.minute, self.hour)
        date_phrase = describe_dates(self.day_of_month, self.month, self.day_of_week)
        return join_phrases(time_phrase, date_phrase)

    def matches(self, moment: datetime) -> bool:
        """True when the schedule would fire during the given minute."""
        return (
            self.minute.matches(moment.minute)
            and self.hour.matches(moment.hour)
            and self.month.matches(moment.month)
            and self._day_matches(moment)
        )

    def _day_matches(self, moment: datetime) -> bool:
        """Apply cron's day rule: two *restricted* day fields are OR-ed, not AND-ed."""
        by_month_day = self.day_of_month.matches(moment.day)
        by_week_day = self.day_of_week.matches(cron_weekday(moment))
        if self.day_of_month.is_unrestricted or self.day_of_week.is_unrestricted:
            return by_month_day and by_week_day
        return by_month_day or by_week_day


def cron_weekday(moment: datetime) -> int:
    """Convert Python's weekday numbering (Monday=0) to cron's (Sunday=0)."""
    return (moment.weekday() + 1) % 7


# ---------------------------------------------------------------------------
# Parsing
# ---------------------------------------------------------------------------


def parse_cron(expression: str) -> CronSchedule:
    """Parse a five-field cron expression.

    Raises:
        CronParseError: if the expression is malformed or a value is out of range.
    """
    tokens = split_into_field_tokens(expression)
    fields = tuple(parse_field(spec, token) for spec, token in zip(FIELD_SPECS, tokens))
    return CronSchedule(expression.strip(), *fields)


def split_into_field_tokens(expression: str) -> tuple[str, ...]:
    """Split an expression on whitespace and check that all five fields are present."""
    if not isinstance(expression, str):
        raise CronParseError(f"expression must be a string, got {type(expression).__name__}")

    tokens = tuple(expression.split())
    if len(tokens) != len(FIELD_SPECS):
        expected = " ".join(spec.name for spec in FIELD_SPECS)
        raise CronParseError(
            f"expected {len(FIELD_SPECS)} fields ({expected}), "
            f"got {len(tokens)} in {expression!r}"
        )
    return tokens


def parse_field(spec: FieldSpec, token: str) -> CronField:
    """Parse one field token, e.g. ``*``, ``1-5``, ``1,3,5`` or ``*/15``."""
    values: set[int] = set()
    for term in split_list_terms(spec, token):
        values.update(parse_term(spec, term))
    return CronField(spec=spec, source=token, values=tuple(sorted(values)))


def split_list_terms(spec: FieldSpec, token: str) -> list[str]:
    """Split a comma-separated field into its terms, rejecting empty entries."""
    terms = token.split(",")
    if any(term == "" for term in terms):
        raise CronParseError(f"{spec.name} field has an empty list entry: {token!r}")
    return terms


def parse_term(spec: FieldSpec, term: str) -> range:
    """Parse a single list term (``*``, ``7``, ``1-5``, ``*/15``, ``1-30/5``)."""
    base_text, step = split_step(spec, term)
    base_values = parse_base(spec, base_text, open_ended=step is not None)
    return base_values[:: step or 1]


def split_step(spec: FieldSpec, term: str) -> tuple[str, int | None]:
    """Split ``base/step`` into its parts. Returns ``(base, None)`` when there is no step."""
    if "/" not in term:
        return term, None

    base_text, _, step_text = term.partition("/")
    if "/" in step_text:
        raise CronParseError(f"{spec.name} field has more than one '/' in {term!r}")

    step = parse_integer(spec, step_text, role="step")
    if step < 1:
        raise CronParseError(f"{spec.name} step must be 1 or greater, got {step} in {term!r}")
    return base_text, step


def parse_base(spec: FieldSpec, text: str, open_ended: bool) -> range:
    """Parse the part of a term before any ``/``: ``*``, ``7`` or ``1-5``.

    ``open_ended`` is True when a step follows, in which case a bare number means
    "from this value to the end of the range" — so ``5/10`` means ``5-59/10`` for minutes.
    """
    if text == "*":
        return spec.full_range
    if "-" in text:
        return parse_range(spec, text)

    value = parse_value(spec, text, role="value")
    return range(value, spec.max_value + 1) if open_ended else range(value, value + 1)


def parse_range(spec: FieldSpec, text: str) -> range:
    """Parse an inclusive ``start-end`` range."""
    start_text, _, end_text = text.partition("-")
    start = parse_value(spec, start_text, role="range start")
    end = parse_value(spec, end_text, role="range end")
    if start > end:
        raise CronParseError(
            f"{spec.name} range start {start} is greater than end {end} in {text!r}"
        )
    return range(start, end + 1)


def parse_value(spec: FieldSpec, text: str, role: str) -> int:
    """Parse an integer and check it against the field's legal range."""
    value = parse_integer(spec, text, role)
    if not (spec.min_value <= value <= spec.max_value):
        raise CronParseError(
            f"{spec.name} {role} {value} is out of range "
            f"({spec.min_value}-{spec.max_value})"
        )
    return value


def parse_integer(spec: FieldSpec, text: str, role: str) -> int:
    """Parse an integer, with a field-aware error message."""
    try:
        return int(text)
    except ValueError:
        raise CronParseError(f"{spec.name} {role} must be a number, got {text!r}") from None


# ---------------------------------------------------------------------------
# Description: time of day
# ---------------------------------------------------------------------------

#: Beyond this many distinct firing times we summarise instead of listing them.
MAX_LISTED_TIMES = 4


def describe_time_of_day(minute: CronField, hour: CronField) -> str:
    """Describe the minute and hour fields, e.g. ``At 12:00`` or ``Every 15 minutes``."""
    if fires_on_a_repeating_interval(minute):
        return describe_interval_schedule(minute, hour)
    return describe_clock_schedule(minute, hour)


def fires_on_a_repeating_interval(minute: CronField) -> bool:
    """True when the minute field is ``*`` or ``*/n`` — an "every N minutes" schedule."""
    return minute.is_unrestricted or minute.wildcard_step is not None


def describe_interval_schedule(minute: CronField, hour: CronField) -> str:
    """Describe schedules that repeat within the hour, e.g. ``Every 15 minutes``."""
    step = minute.wildcard_step
    phrase = "Every minute" if step is None else f"Every {step} minutes"
    if hour.is_unrestricted:
        return phrase
    return f"{phrase} during {describe_hour_window(hour)}"


def describe_hour_window(hour: CronField) -> str:
    """Describe which hours are active, e.g. ``the 12:00 hour`` or ``every 2nd hour``."""
    step = hour.wildcard_step
    if step is not None:
        return f"every {ordinal(step)} hour"

    labels = [f"{value:02d}:00" for value in hour.values]
    noun = "hour" if len(labels) == 1 else "hours"
    return f"the {format_list(labels)} {noun}"


def describe_clock_schedule(minute: CronField, hour: CronField) -> str:
    """Describe schedules that fire at fixed minute marks, e.g. ``At 08:30``."""
    if hour.is_unrestricted:
        return f"At {format_list(minute.values)} minutes past every hour"

    hour_step = hour.wildcard_step
    if hour_step is not None:
        return f"Every {hour_step} hours, {describe_minutes_past_the_hour(minute)}"

    return describe_explicit_clock_times(minute, hour)


def describe_minutes_past_the_hour(minute: CronField) -> str:
    """Describe the minute marks within an hourly cycle, e.g. ``on the hour``."""
    if minute.is_single_value and minute.only_value == 0:
        return "on the hour"
    return f"at {format_list(minute.values)} minutes past the hour"


def describe_explicit_clock_times(minute: CronField, hour: CronField) -> str:
    """Describe a fixed set of wall-clock times, e.g. ``At 08:30 and 17:30``."""
    times = [f"{h:02d}:{m:02d}" for h in hour.values for m in minute.values]

    if times == ["00:00"]:
        return "At midnight"
    if len(times) <= MAX_LISTED_TIMES:
        return f"At {format_list(times)}"

    hour_labels = [f"{h:02d}:00" for h in hour.values]
    return f"At {format_list(minute.values)} minutes past {format_list(hour_labels)}"


# ---------------------------------------------------------------------------
# Description: dates
# ---------------------------------------------------------------------------

DAY_NAMES: tuple[str, ...] = (
    "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday",
)

MONTH_NAMES: tuple[str, ...] = (
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
)


def describe_dates(day_of_month: CronField, month: CronField, day_of_week: CronField) -> str:
    """Describe the three date fields, e.g. ``on the 1st of every month``."""
    day_clause = describe_days(day_of_month, month, day_of_week)
    month_clause = describe_standalone_months(day_of_month, month)
    return join_phrases(day_clause, month_clause)


def describe_days(day_of_month: CronField, month: CronField, day_of_week: CronField) -> str:
    """Combine the two day rules. Cron fires when *either* restricted rule matches."""
    clauses = [
        clause
        for clause in (describe_month_days(day_of_month, month), describe_week_days(day_of_week))
        if clause
    ]
    return " or ".join(clauses)


def describe_month_days(day_of_month: CronField, month: CronField) -> str:
    """Describe the day-of-month field, naming its months, e.g. ``on the 1st of June``."""
    if day_of_month.is_unrestricted:
        return ""

    days = format_list([ordinal(day) for day in day_of_month.values])
    scope = "every month" if month.is_unrestricted else name_values(month, MONTH_NAMES)
    return f"on the {days} of {scope}"


def describe_week_days(day_of_week: CronField) -> str:
    """Describe the day-of-week field, e.g. ``on Monday through Friday``."""
    if day_of_week.is_unrestricted:
        return ""
    return f"on {name_values(day_of_week, DAY_NAMES)}"


def describe_standalone_months(day_of_month: CronField, month: CronField) -> str:
    """Name the months, unless the day-of-month clause already did so."""
    if month.is_unrestricted or not day_of_month.is_unrestricted:
        return ""
    return f"in {name_values(month, MONTH_NAMES)}"


def name_values(field: CronField, names: Sequence[str]) -> str:
    """Name a field's values, collapsing unbroken runs into ``X through Y``."""
    if field.is_contiguous_run:
        return f"{names[field.values[0]]} through {names[field.values[-1]]}"
    return format_list([names[value] for value in field.values])


# ---------------------------------------------------------------------------
# Text helpers
# ---------------------------------------------------------------------------


def join_phrases(*phrases: str) -> str:
    """Join non-empty phrases with single spaces."""
    return " ".join(phrase for phrase in phrases if phrase)


def format_list(items: Sequence[object]) -> str:
    """Join items into an English list: ``a``, ``a and b``, ``a, b, and c``."""
    texts = [str(item) for item in items]
    if len(texts) == 1:
        return texts[0]
    if len(texts) == 2:
        return f"{texts[0]} and {texts[1]}"
    return f"{', '.join(texts[:-1])}, and {texts[-1]}"


def ordinal(number: int) -> str:
    """Render a number as an ordinal: 1 -> ``1st``, 22 -> ``22nd``, 13 -> ``13th``."""
    if 10 <= number % 100 <= 20:
        suffix = "th"
    else:
        suffix = {1: "st", 2: "nd", 3: "rd"}.get(number % 10, "th")
    return f"{number}{suffix}"


