```python
"""
Cron expression parser and human-readable describer.

A cron expression has five whitespace-separated fields:

    minute hour day_of_month month day_of_week

Each field may contain a wildcard ("*"), a single value ("5"), a range
("1-5"), a comma-separated list ("1,3,5"), and/or a step ("*/15",
"1-30/5"). This module parses that syntax into a structured
`CronSchedule` and can render it back out as an English sentence via
`CronSchedule.describe()`.

The code reads top-down as a pipeline:

    parse_cron(expression)
        -> split_into_fields        (string -> 5 raw field strings)
        -> parse_field (x5)         (raw field string -> CronField)
            -> parse_field_part         (one comma-separated piece -> values)
                -> parse_base               (wildcard / range / single value)
                -> apply_step               ("/N" suffix)
        -> CronSchedule(...)

    CronSchedule.describe()
        -> describe_time             (minute + hour  -> "At 08:30" / "Every 15 minutes")
        -> describe_date             (day_of_month + month -> "on the 1st of every month")
        -> describe_day_of_week      (day_of_week -> "on Monday through Friday")
"""

from dataclasses import dataclass
from typing import List, Optional, Tuple


# --------------------------------------------------------------------------
# Errors
# --------------------------------------------------------------------------

class CronParseError(ValueError):
    """Raised when a cron expression (or one of its fields) is invalid."""


# --------------------------------------------------------------------------
# Field range definitions
# --------------------------------------------------------------------------

@dataclass(frozen=True)
class FieldRange:
    """The valid bounds and display name for one cron field."""
    name: str
    minimum: int
    maximum: int


MINUTE = FieldRange("minute", 0, 59)
HOUR = FieldRange("hour", 0, 23)
DAY_OF_MONTH = FieldRange("day_of_month", 1, 31)
MONTH = FieldRange("month", 1, 12)
DAY_OF_WEEK = FieldRange("day_of_week", 0, 6)

# Order matters: this is the order fields appear in a cron expression.
FIELD_RANGES: Tuple[FieldRange, ...] = (MINUTE, HOUR, DAY_OF_MONTH, MONTH, DAY_OF_WEEK)


# --------------------------------------------------------------------------
# Parsed field + schedule data structures
# --------------------------------------------------------------------------

@dataclass(frozen=True)
class CronField:
    """One parsed field of a cron expression, e.g. the "*/15" in minute position."""
    raw: str
    field_range: FieldRange
    values: List[int]            # sorted, de-duplicated, concrete values this field matches
    step: Optional[int] = None   # the "/N" step size, only set for an unambiguous single step


@dataclass(frozen=True)
class CronSchedule:
    """A fully parsed 5-field cron expression."""
    minute: CronField
    hour: CronField
    day_of_month: CronField
    month: CronField
    day_of_week: CronField

    def describe(self) -> str:
        """Render this schedule as a human-readable English sentence."""
        return describe_schedule(self)


# --------------------------------------------------------------------------
# Top-level parsing entry point
# --------------------------------------------------------------------------

def parse_cron(expression: str) -> CronSchedule:
    """Parse a standard 5-field cron expression into a CronSchedule."""
    raw_fields = split_into_fields(expression)
    minute, hour, day_of_month, month, day_of_week = (
        parse_field(raw_field, field_range)
        for raw_field, field_range in zip(raw_fields, FIELD_RANGES)
    )
    return CronSchedule(minute, hour, day_of_month, month, day_of_week)


def split_into_fields(expression: str) -> List[str]:
    """Split a cron expression into its 5 raw field strings, validating the count."""
    fields = expression.split()
    if len(fields) != len(FIELD_RANGES):
        raise CronParseError(
            f"Expected 5 fields (minute hour day_of_month month day_of_week), "
            f"got {len(fields)}: {expression!r}"
        )
    return fields


# --------------------------------------------------------------------------
# Single-field parsing (shared by all 5 fields -- no per-field duplication)
# --------------------------------------------------------------------------

def parse_field(spec: str, field_range: FieldRange) -> CronField:
    """Parse one field's text (e.g. "1-5,10,*/15") into a CronField."""
    if not spec:
        raise CronParseError(f"The {field_range.name} field is empty")

    comma_separated_parts = spec.split(",")
    parsed_parts = [parse_field_part(part, field_range) for part in comma_separated_parts]

    all_values = sorted({value for values, _ in parsed_parts for value in values})

    # A step is only meaningful to report at the field level when the whole
    # field was one unambiguous "base/step" expression (e.g. "*/15"), not
    # when it's mixed into a list like "5,*/15".
    step = parsed_parts[0][1] if len(parsed_parts) == 1 else None

    return CronField(raw=spec, field_range=field_range, values=all_values, step=step)


def parse_field_part(part: str, field_range: FieldRange) -> Tuple[List[int], Optional[int]]:
    """Parse one comma-separated piece of a field, e.g. "1-30/5", "*", or "7"."""
    if "/" in part:
        base_text, step_text = part.split("/", maxsplit=1)
        step = parse_step(step_text, field_range)
    else:
        base_text, step = part, None

    values = parse_base(base_text, field_range)
    if step is not None:
        values = apply_step(values, step)

    return values, step


def parse_base(base_text: str, field_range: FieldRange) -> List[int]:
    """Parse the part of a field before any "/step": "*", a range, or a single value."""
    if base_text == "*":
        return list(range(field_range.minimum, field_range.maximum + 1))
    if "-" in base_text:
        return parse_range(base_text, field_range)
    return [parse_single_value(base_text, field_range)]


def parse_range(base_text: str, field_range: FieldRange) -> List[int]:
    """Parse an inclusive range like "1-5" into [1, 2, 3, 4, 5]."""
    start_text, _, end_text = base_text.partition("-")
    start = parse_single_value(start_text, field_range)
    end = parse_single_value(end_text, field_range)
    if start > end:
        raise CronParseError(
            f"Invalid range '{base_text}' in {field_range.name} field: "
            f"start ({start}) is greater than end ({end})"
        )
    return list(range(start, end + 1))


def parse_single_value(text: str, field_range: FieldRange) -> int:
    """Parse and bounds-check a single integer value within a field."""
    if not text.isdigit():
        raise CronParseError(
            f"Invalid value '{text}' in {field_range.name} field: not an integer"
        )
    value = int(text)
    if not (field_range.minimum <= value <= field_range.maximum):
        raise CronParseError(
            f"Value {value} in {field_range.name} field is out of range "
            f"({field_range.minimum}-{field_range.maximum})"
        )
    return value


def parse_step(step_text: str, field_range: FieldRange) -> int:
    """Parse the "N" in a "/N" step suffix."""
    if not step_text.isdigit() or int(step_text) == 0:
        raise CronParseError(
            f"Invalid step '{step_text}' in {field_range.name} field: "
            f"must be a positive integer"
        )
    return int(step_text)


def apply_step(values: List[int], step: int) -> List[int]:
    """Keep every `step`-th value from an ascending, contiguous list of values."""
    return values[::step]


# --------------------------------------------------------------------------
# Field introspection helpers (used by the describe_* functions below)
# --------------------------------------------------------------------------

def matches_every_value(field: CronField) -> bool:
    """True if a field matches every possible value in its range (e.g. "*")."""
    full_range = range(field.field_range.minimum, field.field_range.maximum + 1)
    return field.values == list(full_range)


def is_single_value(field: CronField) -> bool:
    return len(field.values) == 1


def is_contiguous_range(field: CronField) -> bool:
    """True if the field's values form one unbroken ascending run, e.g. "1-5" or "1,2,3"."""
    return len(field.values) > 1 and field.values == list(range(field.values[0], field.values[-1] + 1))


def starts_at_range_minimum(field: CronField) -> bool:
    return field.values[0] == field.field_range.minimum


def humanize_list(items: List[str]) -> str:
    """Join items into an English list: "A", "A and B", or "A, B, and C"."""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    return ", ".join(items[:-1]) + f", and {items[-1]}"


def ordinal(n: int) -> str:
    """Format an integer as an ordinal, e.g. 1 -> "1st", 22 -> "22nd"."""
    if 10 <= n % 100 <= 20:
        suffix = "th"
    else:
        suffix = {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th")
    return f"{n}{suffix}"


MONTH_NAMES = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
]
WEEKDAY_NAMES = [
    "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday",
]


def describe_numbers(field: CronField) -> str:
    """Describe a field's values as plain numbers: "5", "1 through 5", or "1, 3, and 5"."""
    if is_single_value(field):
        return str(field.values[0])
    if is_contiguous_range(field):
        return f"{field.values[0]} through {field.values[-1]}"
    return humanize_list([str(value) for value in field.values])


# --------------------------------------------------------------------------
# Human-readable description
# --------------------------------------------------------------------------

def describe_schedule(schedule: CronSchedule) -> str:
    """Combine the time, date, and weekday phrases into one sentence."""
    phrases = [
        describe_time(schedule.minute, schedule.hour),
        describe_date(schedule.day_of_month, schedule.month),
        describe_day_of_week(schedule.day_of_week),
    ]
    return " ".join(phrase for phrase in phrases if phrase)


def describe_time(minute: CronField, hour: CronField) -> str:
    """Describe the minute/hour portion, e.g. "At 08:30" or "Every 15 minutes"."""
    every_minute = matches_every_value(minute) and minute.step is None
    every_hour = matches_every_value(hour) and hour.step is None

    if every_minute and every_hour:
        return "Every minute"

    if minute.step and starts_at_range_minimum(minute) and every_hour:
        return f"Every {minute.step} minutes"

    if is_single_value(minute) and minute.values[0] == 0 and hour.step and starts_at_range_minimum(hour):
        return f"Every {hour.step} hours, on the hour"

    return f"At {describe_time_of_day(minute, hour)}"


def describe_time_of_day(minute: CronField, hour: CronField) -> str:
    """Describe a specific clock time, e.g. "midnight" or "12:00"."""
    if is_single_value(minute) and is_single_value(hour):
        hour_value, minute_value = hour.values[0], minute.values[0]
        if hour_value == 0 and minute_value == 0:
            return "midnight"
        return f"{hour_value:02d}:{minute_value:02d}"

    # Less common case: multiple/ranged minutes and/or hours, e.g. "0,30 8-10 * * *"
    return f"minute {describe_numbers(minute)} past hour {describe_numbers(hour)}"


def describe_date(day_of_month: CronField, month: CronField) -> Optional[str]:
    """Describe the day-of-month/month portion, e.g. "on the 1st of every month"."""
    day_is_restricted = not matches_every_value(day_of_month)
    month_is_restricted = not matches_every_value(month)

    if not day_is_restricted and not month_is_restricted:
        return None

    month_phrase = describe_months(month) if month_is_restricted else "every month"

    if not day_is_restricted:
        return f"in {month_phrase}"

    return f"on {describe_days_of_month(day_of_month)} of {month_phrase}"


def describe_days_of_month(field: CronField) -> str:
    """Describe day-of-month values with ordinals, e.g. "the 1st" or "the 1st and 15th"."""
    if is_single_value(field):
        return f"the {ordinal(field.values[0])}"
    if is_contiguous_range(field):
        return f"the {ordinal(field.values[0])} through {ordinal(field.values[-1])}"
    return "the " + humanize_list([ordinal(value) for value in field.values])


def describe_months(field: CronField) -> str:
    """Describe month values by name, e.g. "January" or "January through March"."""
    names = [MONTH_NAMES[value - 1] for value in field.values]
    if is_single_value(field):
        return names[0]
    if is_contiguous_range(field):
        return f"{names[0]} through {names[-1]}"
    return humanize_list(names)


def describe_day_of_week(field: CronField) -> Optional[str]:
    """Describe day-of-week values by name, e.g. "on Monday through Friday"."""
    if matches_every_value(field):
        return None

    names = [WEEKDAY_NAMES[value] for value in field.values]
    if is_single_value(field):
        phrase = names[0]
    elif is_contiguous_range(field):
        phrase = f"{names[0]} through {names[-1]}"
    else:
        phrase = humanize_list(names)
    return f"on {phrase}"


