        and only_part.step == 1
    ):
        return f"{names[only_part.start]} through {names[only_part.end]}"

    selected_names = [names[value] for value in field.values]
    return _join_english(selected_names)


def _describe_month_selection(field: ParsedField) -> str:
    names = (
        "",
        "January",
        "February",
        "March",
        "April",
        "May",
        "June",
        "July",
        "August",
        "September",
        "October",
        "November",
        "December",
    )

    if field.is_unrestricted:
        return "every month"

    wildcard_step = field.wildcard_step
    if wildcard_step is not None:
        return (
            f"every {_ordinal(wildcard_step)} month, "
            "starting with January"
        )

    exact_value = field.exact_value
    if exact_value is not None:
        return names[exact_value]

    only_part = field.only_part
    if (
        only_part is not None
        and only_part.kind is PartKind.RANGE
        and only_part.step == 1
    ):
        return f"{names[only_part.start]} through {names[only_part.end]}"

    selected_names = [names[value] for value in field.values]
    return _join_english(selected_names)


# ---------------------------------------------------------------------------
# General formatting helpers
# ---------------------------------------------------------------------------


def _format_clock(hour: int, minute: int) -> str:
    return f"{hour:02d}:{minute:02d}"


def _ordinal(value: int) -> str:
    remainder = value % 100

    if 10 <= remainder <= 20:
        suffix = "th"
    else:
        suffix = {
            1: "st",
            2: "nd",
            3: "rd",
        }.get(value % 10, "th")

    return f"{value}{suffix}"


def _join_english(items: Sequence[str]) -> str:
    """Join items with commas and a final conjunction."""

    if not items:
        return ""

    if len(items) == 1:
        return items[0]

    if len(items) == 2:
        return f"{items[0]} and {items[1]}"

    return f"{', '.join(items[:-1])}, and {items[-1]}"
```

`parse_cron()` returns the structured `CronSchedule`; its expanded field values are available through properties such as `schedule.minute.values`, and the corresponding English text comes from `schedule.describe()`.
